137→          <Button
138→            variant="ghost"
139→            size="icon-xs"
140→            className="text-muted-foreground"
141→            onClick={() => {
142→              setShowAdvancedCards(false);
143→              closeNewAgent();
144→            }}
145→          >
146→            <span className="text-lg leading-none">&times;</span>
147→          </Button>
148→        </div>
149→
150→        <div className="p-6 space-y-6">
151→          {!showAdvancedCards ? (
152→            <>
153→              {/* Recommendation */}
154→              <div className="text-center space-y-3">
155→                <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-accent">
156→                  <Sparkles className="h-6 w-6 text-foreground" />
157→                </div>
158→                <p className="text-sm text-muted-foreground">
159→                  We recommend letting your CEO handle agent setup — they know the
