170→              {/* Advanced link */}
171→              <div className="text-center">
172→                <button
173→                  className="text-xs text-muted-foreground hover:text-foreground underline underline-offset-2 transition-colors"
174→                  onClick={handleAdvancedConfig}
175→                >
176→                  I want advanced configuration myself
177→                </button>
178→              </div>
