180→          ) : (
181→            <>
182→              <div className="space-y-2">
183→                <button
184→                  className="inline-flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground transition-colors"
185→                  onClick={() => setShowAdvancedCards(false)}
186→                >
