 1→export type NormalizedAgentPermissions = Record<string, unknown> & {
 2→  canCreateAgents: boolean;
 3→};
 4→
 5→export function defaultPermissionsForRole(role: string): NormalizedAgentPermissions {
 6→  return {
 7→    canCreateAgents: role === "ceo",
 8→  };
 9→}
10→
11→export function normalizeAgentPermissions(
12→  permissions: unknown,
13→  role: string,
14→): NormalizedAgentPermissions {
15→  const defaults = defaultPermissionsForRole(role);
16→  if (typeof permissions !== "object" || permissions === null || Array.isArray(permissions)) {
17→    return defaults;
18→  }
19→
20→  const record = permissions as Record<string, unknown>;
21→  return {
22→    canCreateAgents:
23→      typeof record.canCreateAgents === "boolean"
24→        ? record.canCreateAgents
25→        : defaults.canCreateAgents,
26→  };
27→}
