 28→const CONFIG_REVISION_FIELDS = [
 29→  "name",
 30→  "role",
 31→  "title",
 32→  "reportsTo",
 33→  "capabilities",
 34→  "adapterType",
 35→  "adapterConfig",
 36→  "runtimeConfig",
 37→  "budgetMonthlyCents",
 38→  "metadata",
 39→] as const;
 40→
 41→type ConfigRevisionField = (typeof CONFIG_REVISION_FIELDS)[number];
 42→type AgentConfigSnapshot = Pick<typeof agents.$inferSelect, ConfigRevisionField>;
 43→
 44→interface RevisionMetadata {
 45→  createdByAgentId?: string | null;
 46→  createdByUserId?: string | null;
 47→  source?: string;
 48→  rolledBackFromRevisionId?: string | null;
 49→}
 50→
 51→interface UpdateAgentOptions {
 52→  recordRevision?: RevisionMetadata;
 53→}
 54→
 55→interface AgentShortnameRow {
 56→  id: string;
 57→  name: string;
 58→  status: string;
 59→}
 60→
 61→interface AgentShortnameCollisionOptions {
 62→  excludeAgentId?: string | null;
 63→}
 64→
 65→function isPlainRecord(value: unknown): value is Record<string, unknown> {
 66→  return typeof value === "object" && value !== null && !Array.isArray(value);
 67→}
 68→
 69→function jsonEqual(left: unknown, right: unknown): boolean {
 70→  return JSON.stringify(left) === JSON.stringify(right);
 71→}
 72→
 73→function buildConfigSnapshot(
 74→  row: Pick<typeof agents.$inferSelect, ConfigRevisionField>,
 75→): AgentConfigSnapshot {
 76→  const adapterConfig =
 77→    typeof row.adapterConfig === "object" && row.adapterConfig !== null && !Array.isArray(row.adapterConfig)
 78→      ? sanitizeRecord(row.adapterConfig as Record<string, unknown>)
 79→      : {};
 80→  const runtimeConfig =
 81→    typeof row.runtimeConfig === "object" && row.runtimeConfig !== null && !Array.isArray(row.runtimeConfig)
 82→      ? sanitizeRecord(row.runtimeConfig as Record<string, unknown>)
 83→      : {};
 84→  const metadata =
 85→    typeof row.metadata === "object" && row.metadata !== null && !Array.isArray(row.metadata)
 86→      ? sanitizeRecord(row.metadata as Record<string, unknown>)
 87→      : row.metadata ?? null;
 88→  return {
 89→    name: row.name,
 90→    role: row.role,
 91→    title: row.title,
 92→    reportsTo: row.reportsTo,
 93→    capabilities: row.capabilities,
 94→    adapterType: row.adapterType,
 95→    adapterConfig,
 96→    runtimeConfig,
 97→    budgetMonthlyCents: row.budgetMonthlyCents,
 98→    metadata,
 99→  };
100→}
101→
102→function containsRedactedMarker(value: unknown): boolean {
103→  if (value === REDACTED_EVENT_VALUE) return true;
104→  if (Array.isArray(value)) return value.some((item) => containsRedactedMarker(item));
105→  if (typeof value !== "object" || value === null) return false;
106→  return Object.values(value as Record<string, unknown>).some((entry) => containsRedactedMarker(entry));
107→}
108→
109→function hasConfigPatchFields(data: Partial<typeof agents.$inferInsert>) {
110→  return CONFIG_REVISION_FIELDS.some((field) => Object.prototype.hasOwnProperty.call(data, field));
111→}
112→
113→function diffConfigSnapshot(
114→  before: AgentConfigSnapshot,
115→  after: AgentConfigSnapshot,
116→): string[] {
117→  return CONFIG_REVISION_FIELDS.filter((field) => !jsonEqual(before[field], after[field]));
118→}
119→
120→function configPatchFromSnapshot(snapshot: unknown): Partial<typeof agents.$inferInsert> {
121→  if (!isPlainRecord(snapshot)) throw unprocessable("Invalid revision snapshot");
122→
123→  if (typeof snapshot.name !== "string" || snapshot.name.length === 0) {
124→    throw unprocessable("Invalid revision snapshot: name");
125→  }
126→  if (typeof snapshot.role !== "string" || snapshot.role.length === 0) {
127→    throw unprocessable("Invalid revision snapshot: role");
128→  }
129→  if (typeof snapshot.adapterType !== "string" || snapshot.adapterType.length === 0) {
130→    throw unprocessable("Invalid revision snapshot: adapterType");
131→  }
132→  if (typeof snapshot.budgetMonthlyCents !== "number" || !Number.isFinite(snapshot.budgetMonthlyCents)) {
133→    throw unprocessable("Invalid revision snapshot: budgetMonthlyCents");
134→  }
135→
136→  return {
137→    name: snapshot.name,
138→    role: snapshot.role,
139→    title: typeof snapshot.title === "string" || snapshot.title === null ? snapshot.title : null,
140→    reportsTo:
141→      typeof snapshot.reportsTo === "string" || snapshot.reportsTo === null ? snapshot.reportsTo : null,
142→    capabilities:
143→      typeof snapshot.capabilities === "string" || snapshot.capabilities === null
144→        ? snapshot.capabilities
145→        : null,
146→    adapterType: snapshot.adapterType,
147→    adapterConfig: isPlainRecord(snapshot.adapterConfig) ? snapshot.adapterConfig : {},
148→    runtimeConfig: isPlainRecord(snapshot.runtimeConfig) ? snapshot.runtimeConfig : {},
149→    budgetMonthlyCents: Math.max(0, Math.floor(snapshot.budgetMonthlyCents)),
150→    metadata: isPlainRecord(snapshot.metadata) || snapshot.metadata === null ? snapshot.metadata : null,
151→  };
152→}
