185→export function agentService(db: Db) {
186→  function currentUtcMonthWindow(now = new Date()) {
187→    const year = now.getUTCFullYear();
188→    const month = now.getUTCMonth();
189→    return {
190→      start: new Date(Date.UTC(year, month, 1, 0, 0, 0, 0)),
191→      end: new Date(Date.UTC(year, month + 1, 1, 0, 0, 0, 0)),
192→    };
193→  }
194→
195→  function withUrlKey<T extends { id: string; name: string }>(row: T) {
196→    return {
197→      ...row,
198→      urlKey: normalizeAgentUrlKey(row.name) ?? row.id,
199→    };
200→  }

