import { and, count, eq } from "drizzle-orm";
import type { Db } from "@paperclipai/db";
import {
  companies,
  agents,
  companyMemberships,
  instanceUserRoles,
} from "@paperclipai/db";
import { logger } from "../middleware/logger.js";

export interface BootstrapResult {
  action: "created_company" | "assigned_to_company" | "noop";
  companyId?: string;
}

export function bootstrapService(db: Db) {
  const isEnabled = process.env.PAPERCLIP_AUTO_BOOTSTRAP !== "false";

  async function maybeBootstrapUser(
    userId: string,
    userName?: string | null,
  ): Promise<BootstrapResult> {
    if (!isEnabled) return { action: "noop" };

    // Check if user already has any company memberships
    const existingMemberships = await db
      .select({ id: companyMemberships.id })
      .from(companyMemberships)
      .where(
        and(
          eq(companyMemberships.principalType, "user"),
          eq(companyMemberships.principalId, userId),
          eq(companyMemberships.status, "active"),
        ),
      )
      .limit(1);

    if (existingMemberships.length > 0) {
      return { action: "noop" };
    }

    // Check if any companies exist
    const [companyCount] = await db
      .select({ count: count() })
      .from(companies);

    if (companyCount.count === 0) {
      // First user: create default company + agent, promote to admin
      return createDefaultSetup(userId, userName);
    }

    // Companies exist but user has no membership: assign to first company
    const [firstCompany] = await db
      .select({ id: companies.id })
      .from(companies)
      .limit(1);

    if (firstCompany) {
      await db.insert(companyMemberships).values({
        companyId: firstCompany.id,
        principalType: "user",
        principalId: userId,
        status: "active",
        membershipRole: "member",
      });

      logger.info(
        { userId, companyId: firstCompany.id },
        "Auto-assigned user to existing company",
      );

      return { action: "assigned_to_company", companyId: firstCompany.id };
    }

    return { action: "noop" };
  }

  async function createDefaultSetup(
    userId: string,
    userName?: string | null,
  ): Promise<BootstrapResult> {
    const companyName =
      process.env.PAPERCLIP_DEFAULT_COMPANY_NAME || "My Company";
    const agentName =
      process.env.PAPERCLIP_DEFAULT_AGENT_NAME || "Assistant";

    // Create company
    const [company] = await db
      .insert(companies)
      .values({ name: companyName })
      .returning();

    // Promote user to instance_admin
    const existingRole = await db
      .select({ id: instanceUserRoles.id })
      .from(instanceUserRoles)
      .where(
        and(
          eq(instanceUserRoles.userId, userId),
          eq(instanceUserRoles.role, "instance_admin"),
        ),
      )
      .then((rows) => rows[0] ?? null);

    if (!existingRole) {
      await db.insert(instanceUserRoles).values({
        userId,
        role: "instance_admin",
      });
    }

    // Assign user as owner
    await db.insert(companyMemberships).values({
      companyId: company.id,
      principalType: "user",
      principalId: userId,
      status: "active",
      membershipRole: "owner",
    });

    // Create default agent
    await db.insert(agents).values({
      companyId: company.id,
      name: agentName,
      role: "general",
      adapterType: "claude-local",
    });

    logger.info(
      { userId, companyId: company.id, companyName, agentName },
      "Auto-bootstrap: created default company and agent for first user",
    );

    return { action: "created_company", companyId: company.id };
  }

  return { maybeBootstrapUser };
}

import { createDb } from "./client.js";
import { companies, agents, goals, projects, issues } from "./schema/index.js";

const url = process.env.DATABASE_URL;
if (!url) throw new Error("DATABASE_URL is required");

const db = createDb(url);

console.log("Seeding database...");

const [company] = await db
  .insert(companies)
  .values({
    name: "Paperclip Demo Co",
    description: "A demo autonomous company",
    status: "active",
    budgetMonthlyCents: 50000,
  })
  .returning();

const [ceo] = await db
  .insert(agents)
  .values({
    companyId: company!.id,
    name: "CEO Agent",
    role: "ceo",
    title: "Chief Executive Officer",
    status: "idle",
    adapterType: "process",
    adapterConfig: { command: "echo", args: ["hello from ceo"] },
    budgetMonthlyCents: 15000,
  })
  .returning();

const [engineer] = await db
  .insert(agents)
  .values({
    companyId: company!.id,
    name: "Engineer Agent",
    role: "engineer",
    title: "Software Engineer",
    status: "idle",
    reportsTo: ceo!.id,
    adapterType: "process",
    adapterConfig: { command: "echo", args: ["hello from engineer"] },
    budgetMonthlyCents: 10000,
  })
  .returning();

const [goal] = await db
  .insert(goals)
  .values({
    companyId: company!.id,
    title: "Ship V1",
    description: "Deliver first control plane release",
    level: "company",
    status: "active",
    ownerAgentId: ceo!.id,
  })
  .returning();

const [project] = await db
  .insert(projects)
  .values({
    companyId: company!.id,
    goalId: goal!.id,
    name: "Control Plane MVP",
    description: "Implement core board + agent loop",
    status: "in_progress",
    leadAgentId: ceo!.id,
  })
  .returning();

await db.insert(issues).values([
  {
    companyId: company!.id,
    projectId: project!.id,
    goalId: goal!.id,
    title: "Implement atomic task checkout",
    description: "Ensure in_progress claiming is conflict-safe",
    status: "todo",
    priority: "high",
    assigneeAgentId: engineer!.id,
    createdByAgentId: ceo!.id,
  },
  {
    companyId: company!.id,
    projectId: project!.id,
    goalId: goal!.id,
    title: "Add budget auto-pause",
    description: "Pause agent at hard budget ceiling",
    status: "backlog",
    priority: "medium",
    createdByAgentId: ceo!.id,
  },
]);

console.log("Seed complete");
process.exit(0);

