 93→function inferLanguage(relativePath: string): string {
 94→  const lower = relativePath.toLowerCase();
 95→  if (lower.endsWith(".md")) return "markdown";
 96→  if (lower.endsWith(".json")) return "json";
 97→  if (lower.endsWith(".yaml") || lower.endsWith(".yml")) return "yaml";
 98→  if (lower.endsWith(".ts") || lower.endsWith(".tsx")) return "typescript";
 99→  if (lower.endsWith(".js") || lower.endsWith(".jsx") || lower.endsWith(".mjs") || lower.endsWith(".cjs")) {
100→    return "javascript";
101→  }
102→  if (lower.endsWith(".sh")) return "bash";
103→  if (lower.endsWith(".py")) return "python";
104→  if (lower.endsWith(".toml")) return "toml";
105→  if (lower.endsWith(".txt")) return "text";
106→  return "text";
107→}
108→
109→function isMarkdown(relativePath: string) {
110→  return relativePath.toLowerCase().endsWith(".md");
111→}
112→
113→function normalizeRelativeFilePath(candidatePath: string): string {
114→  const normalized = path.posix.normalize(candidatePath.replaceAll("\\", "/")).replace(/^\/+/, "");
115→  if (!normalized || normalized === "." || normalized === ".." || normalized.startsWith("../")) {
116→    throw unprocessable("Instructions file path must stay within the bundle root");
117→  }
118→  return normalized;
119→}
120→
121→function resolvePathWithinRoot(rootPath: string, relativePath: string): string {
122→  const normalizedRelativePath = normalizeRelativeFilePath(relativePath);
123→  const absoluteRoot = path.resolve(rootPath);
124→  const absolutePath = path.resolve(absoluteRoot, normalizedRelativePath);
125→  const relativeToRoot = path.relative(absoluteRoot, absolutePath);
126→  if (relativeToRoot === ".." || relativeToRoot.startsWith(`..${path.sep}`)) {
127→    throw unprocessable("Instructions file path must stay within the bundle root");
128→  }
129→  return absolutePath;
130→}
