143→function resolveLegacyInstructionsPath(candidatePath: string, config: Record<string, unknown>): string {
144→  if (path.isAbsolute(candidatePath)) return candidatePath;
145→  const cwd = asString(config.cwd);
146→  if (!cwd || !path.isAbsolute(cwd)) {
147→    throw unprocessable(
148→      "Legacy relative instructionsFilePath requires adapterConfig.cwd to be set to an absolute path",
149→    );
150→  }
151→  return path.resolve(cwd, candidatePath);
152→}
153→
154→async function statIfExists(targetPath: string) {
155→  return fs.stat(targetPath).catch(() => null);
156→}
157→
158→function shouldIgnoreInstructionsEntry(entry: { name: string; isDirectory(): boolean; isFile(): boolean }) {
159→  if (entry.name === "." || entry.name === "..") return true;
160→  if (entry.isDirectory()) {
161→    return IGNORED_INSTRUCTIONS_DIRECTORY_NAMES.has(entry.name);
162→  }
163→  if (!entry.isFile()) return false;
164→  return (
165→    IGNORED_INSTRUCTIONS_FILE_NAMES.has(entry.name)
166→    || entry.name.startsWith("._")
167→    || entry.name.endsWith(".pyc")
168→    || entry.name.endsWith(".pyo")
169→  );
170→}
