172→async function listFilesRecursive(rootPath: string): Promise<string[]> {
173→  const output: string[] = [];
174→
175→  async function walk(currentPath: string, relativeDir: string) {
176→    const entries = await fs.readdir(currentPath, { withFileTypes: true }).catch(() => []);
177→    for (const entry of entries) {
178→      if (shouldIgnoreInstructionsEntry(entry)) continue;
179→      const absolutePath = path.join(currentPath, entry.name);
180→      const relativePath = normalizeRelativeFilePath(
181→        relativeDir ? path.posix.join(relativeDir, entry.name) : entry.name,
182→      );
183→      if (entry.isDirectory()) {
184→        await walk(absolutePath, relativePath);
185→        continue;
186→      }
187→      if (!entry.isFile()) continue;
188→      output.push(relativePath);
189→    }
190→  }
191→
192→  await walk(rootPath, "");
193→  return output.sort((left, right) => left.localeCompare(right));
194→}
