196→async function readFileSummary(rootPath: string, relativePath: string, entryFile: string): Promise<AgentInstructionsFileSummary> {
197→  const absolutePath = resolvePathWithinRoot(rootPath, relativePath);
198→  const stat = await fs.stat(absolutePath);
199→  return {
200→    path: relativePath,
201→    size: stat.size,
202→    language: inferLanguage(relativePath),
203→    markdown: isMarkdown(relativePath),
204→    isEntryFile: relativePath === entryFile,
205→    editable: true,
206→    deprecated: false,
207→    virtual: false,
208→  };
209→}
