 35→/**
 36→ * Create a tmpdir with `.claude/skills/` containing symlinks to skills from
 37→ * the repo's `skills/` directory, so `--add-dir` makes Claude Code discover
 38→ * them as proper registered skills.
 39→ */
 40→async function buildSkillsDir(config: Record<string, unknown>): Promise<string> {
 41→  const tmp = await fs.mkdtemp(path.join(os.tmpdir(), "paperclip-skills-"));
 42→  const target = path.join(tmp, ".claude", "skills");
 43→  await fs.mkdir(target, { recursive: true });
 44→  const availableEntries = await readPaperclipRuntimeSkillEntries(config, __moduleDir);
 45→  const desiredNames = new Set(
 46→    resolveClaudeDesiredSkillNames(
 47→      config,
 48→      availableEntries,
 49→    ),
 50→  );
 51→  for (const entry of availableEntries) {
 52→    if (!desiredNames.has(entry.key)) continue;
 53→    await fs.symlink(
 54→      entry.source,
 55→      path.join(target, entry.runtimeName),
 56→    );
 57→  }
 58→  return tmp;
 59→}
