105→async function buildClaudeRuntimeConfig(input: ClaudeExecutionInput): Promise<ClaudeRuntimeConfig> {
106→  const { runId, agent, config, context, authToken } = input;
107→
108→  const command = asString(config.command, "claude");
109→  const workspaceContext = parseObject(context.paperclipWorkspace);
110→  const workspaceCwd = asString(workspaceContext.cwd, "");
111→  const workspaceSource = asString(workspaceContext.source, "");
112→  const workspaceStrategy = asString(workspaceContext.strategy, "");
113→  const workspaceId = asString(workspaceContext.workspaceId, "") || null;
114→  const workspaceRepoUrl = asString(workspaceContext.repoUrl, "") || null;
115→  const workspaceRepoRef = asString(workspaceContext.repoRef, "") || null;
116→  const workspaceBranch = asString(workspaceContext.branchName, "") || null;
117→  const workspaceWorktreePath = asString(workspaceContext.worktreePath, "") || null;
118→  const agentHome = asString(workspaceContext.agentHome, "") || null;
119→  const workspaceHints = Array.isArray(context.paperclipWorkspaces)
120→    ? context.paperclipWorkspaces.filter(
121→        (value): value is Record<string, unknown> => typeof value === "object" && value !== null,
122→      )
123→    : [];
124→  const runtimeServiceIntents = Array.isArray(context.paperclipRuntimeServiceIntents)
125→    ? context.paperclipRuntimeServiceIntents.filter(
126→        (value): value is Record<string, unknown> => typeof value === "object" && value !== null,
127→      )
128→    : [];
129→  const runtimeServices = Array.isArray(context.paperclipRuntimeServices)
130→    ? context.paperclipRuntimeServices.filter(
131→        (value): value is Record<string, unknown> => typeof value === "object" && value !== null,
132→      )
133→    : [];
134→  const runtimePrimaryUrl = asString(context.paperclipRuntimePrimaryUrl, "");
135→  const configuredCwd = asString(config.cwd, "");
136→  const useConfiguredInsteadOfAgentHome = workspaceSource === "agent_home" && configuredCwd.length > 0;
137→  const effectiveWorkspaceCwd = useConfiguredInsteadOfAgentHome ? "" : workspaceCwd;
138→  const cwd = effectiveWorkspaceCwd || configuredCwd || process.cwd();
139→  await ensureAbsoluteDirectory(cwd, { createIfMissing: true });
140→
141→  const envConfig = parseObject(config.env);
142→  const hasExplicitApiKey =
143→    typeof envConfig.PAPERCLIP_API_KEY === "string" && envConfig.PAPERCLIP_API_KEY.trim().length > 0;
144→  const env: Record<string, string> = { ...buildPaperclipEnv(agent) };
145→  env.PAPERCLIP_RUN_ID = runId;
146→
147→  const wakeTaskId =
148→    (typeof context.taskId === "string" && context.taskId.trim().length > 0 && context.taskId.trim()) ||
149→    (typeof context.issueId === "string" && context.issueId.trim().length > 0 && context.issueId.trim()) ||
150→    null;
151→  const wakeReason =
152→    typeof context.wakeReason === "string" && context.wakeReason.trim().length > 0
153→      ? context.wakeReason.trim()
154→      : null;
155→  const wakeCommentId =
156→    (typeof context.wakeCommentId === "string" && context.wakeCommentId.trim().length > 0 && context.wakeCommentId.trim()) ||
157→    (typeof context.commentId === "string" && context.commentId.trim().length > 0 && context.commentId.trim()) ||
158→    null;
159→  const approvalId =
160→    typeof context.approvalId === "string" && context.approvalId.trim().length > 0
161→      ? context.approvalId.trim()
162→      : null;
163→  const approvalStatus =
164→    typeof context.approvalStatus === "string" && context.approvalStatus.trim().length > 0
165→      ? context.approvalStatus.trim()
166→      : null;
167→  const linkedIssueIds = Array.isArray(context.issueIds)
168→    ? context.issueIds.filter((value): value is string => typeof value === "string" && value.trim().length > 0)
169→    : [];
170→
171→  if (wakeTaskId) {
172→    env.PAPERCLIP_TASK_ID = wakeTaskId;
173→  }
174→  if (wakeReason) {
175→    env.PAPERCLIP_WAKE_REASON = wakeReason;
176→  }
177→  if (wakeCommentId) {
178→    env.PAPERCLIP_WAKE_COMMENT_ID = wakeCommentId;
179→  }
180→  if (approvalId) {
181→    env.PAPERCLIP_APPROVAL_ID = approvalId;
182→  }
183→  if (approvalStatus) {
184→    env.PAPERCLIP_APPROVAL_STATUS = approvalStatus;
185→  }
186→  if (linkedIssueIds.length > 0) {
187→    env.PAPERCLIP_LINKED_ISSUE_IDS = linkedIssueIds.join(",");
188→  }
189→  if (effectiveWorkspaceCwd) {
190→    env.PAPERCLIP_WORKSPACE_CWD = effectiveWorkspaceCwd;
191→  }
192→  if (workspaceSource) {
193→    env.PAPERCLIP_WORKSPACE_SOURCE = workspaceSource;
194→  }
195→  if (workspaceStrategy) {
196→    env.PAPERCLIP_WORKSPACE_STRATEGY = workspaceStrategy;
197→  }
198→  if (workspaceId) {
199→    env.PAPERCLIP_WORKSPACE_ID = workspaceId;
200→  }
201→  if (workspaceRepoUrl) {
202→    env.PAPERCLIP_WORKSPACE_REPO_URL = workspaceRepoUrl;
203→  }
204→  if (workspaceRepoRef) {
205→    env.PAPERCLIP_WORKSPACE_REPO_REF = workspaceRepoRef;
206→  }
207→  if (workspaceBranch) {
208→    env.PAPERCLIP_WORKSPACE_BRANCH = workspaceBranch;
209→  }
210→  if (workspaceWorktreePath) {
211→    env.PAPERCLIP_WORKSPACE_WORKTREE_PATH = workspaceWorktreePath;
212→  }
213→  if (agentHome) {
214→    env.AGENT_HOME = agentHome;
215→  }
216→  if (workspaceHints.length > 0) {
217→    env.PAPERCLIP_WORKSPACES_JSON = JSON.stringify(workspaceHints);
218→  }
219→  if (runtimeServiceIntents.length > 0) {
220→    env.PAPERCLIP_RUNTIME_SERVICE_INTENTS_JSON = JSON.stringify(runtimeServiceIntents);
221→  }
222→  if (runtimeServices.length > 0) {
223→    env.PAPERCLIP_RUNTIME_SERVICES_JSON = JSON.stringify(runtimeServices);
224→  }
225→  if (runtimePrimaryUrl) {
226→    env.PAPERCLIP_RUNTIME_PRIMARY_URL = runtimePrimaryUrl;
227→  }
228→
229→  for (const [key, value] of Object.entries(envConfig)) {
230→    if (typeof value === "string") env[key] = value;
231→  }
232→
233→  if (!hasExplicitApiKey && authToken) {
234→    env.PAPERCLIP_API_KEY = authToken;
235→  }
236→
237→  const runtimeEnv = ensurePathInEnv({ ...process.env, ...env });
238→  await ensureCommandResolvable(command, cwd, runtimeEnv);
239→
240→  const timeoutSec = asNumber(config.timeoutSec, 0);
241→  const graceSec = asNumber(config.graceSec, 20);
242→  const extraArgs = (() => {
243→    const fromExtraArgs = asStringArray(config.extraArgs);
244→    if (fromExtraArgs.length > 0) return fromExtraArgs;
245→    return asStringArray(config.args);
246→  })();
247→
248→  return {
249→    command,
250→    cwd,
251→    workspaceId,
252→    workspaceRepoUrl,
253→    workspaceRepoRef,
254→    env,
255→    timeoutSec,
256→    graceSec,
257→    extraArgs,
258→  };
259→}
