261→export async function runClaudeLogin(input: {
262→  runId: string;
263→  agent: AdapterExecutionContext["agent"];
264→  config: Record<string, unknown>;
265→  context?: Record<string, unknown>;
266→  authToken?: string;
267→  onLog?: (stream: "stdout" | "stderr", chunk: string) => Promise<void>;
268→}) {
269→  const onLog = input.onLog ?? (async () => {});
270→  const runtime = await buildClaudeRuntimeConfig({
271→    runId: input.runId,
272→    agent: input.agent,
273→    config: input.config,
274→    context: input.context ?? {},
275→    authToken: input.authToken,
276→  });
277→
278→  const proc = await runChildProcess(input.runId, runtime.command, ["login"], {
279→    cwd: runtime.cwd,
280→    env: runtime.env,
281→    timeoutSec: runtime.timeoutSec,
282→    graceSec: runtime.graceSec,
283→    onLog,
284→  });
285→
286→  const loginMeta = detectClaudeLoginRequired({
287→    parsed: null,
288→    stdout: proc.stdout,
289→    stderr: proc.stderr,
290→  });
291→
292→  return buildLoginResult({
293→    proc,
294→    loginUrl: loginMeta.loginUrl,
295→  });
296→}
