298→export async function execute(ctx: AdapterExecutionContext): Promise<AdapterExecutionResult> {
299→  const { runId, agent, runtime, config, context, onLog, onMeta, onSpawn, authToken } = ctx;
300→
301→  const promptTemplate = asString(
302→    config.promptTemplate,
303→    "You are agent {{agent.id}} ({{agent.name}}). Continue your Paperclip work.",
304→  );
305→  const model = asString(config.model, "");
306→  const effort = asString(config.effort, "");
307→  const chrome = asBoolean(config.chrome, false);
308→  const maxTurns = asNumber(config.maxTurnsPerRun, 0);
309→  const dangerouslySkipPermissions = asBoolean(config.dangerouslySkipPermissions, false);
310→  const instructionsFilePath = asString(config.instructionsFilePath, "").trim();
311→  const instructionsFileDir = instructionsFilePath ? `${path.dirname(instructionsFilePath)}/` : "";
312→  const commandNotes = instructionsFilePath
313→    ? [
314→        `Injected agent instructions via --append-system-prompt-file ${instructionsFilePath} (with path directive appended)`,
315→      ]
316→    : [];
317→
318→  const runtimeConfig = await buildClaudeRuntimeConfig({
319→    runId,
320→    agent,
321→    config,
322→    context,
323→    authToken,
324→  });
325→  const {
326→    command,
327→    cwd,
328→    workspaceId,
329→    workspaceRepoUrl,
330→    workspaceRepoRef,
331→    env,
332→    timeoutSec,
333→    graceSec,
334→    extraArgs,
335→  } = runtimeConfig;
336→  const effectiveEnv = Object.fromEntries(
337→    Object.entries({ ...process.env, ...env }).filter(
338→      (entry): entry is [string, string] => typeof entry[1] === "string",
339→    ),
340→  );
341→  const billingType = resolveClaudeBillingType(effectiveEnv);
342→  const skillsDir = await buildSkillsDir(config);
343→
344→  // When instructionsFilePath is configured, create a combined temp file that
345→  // includes both the file content and the path directive, so we only need
346→  // --append-system-prompt-file (Claude CLI forbids using both flags together).
347→  let effectiveInstructionsFilePath: string | undefined = instructionsFilePath;
348→  if (instructionsFilePath) {
349→    try {
350→      const instructionsContent = await fs.readFile(instructionsFilePath, "utf-8");
351→      const pathDirective = `\nThe above agent instructions were loaded from ${instructionsFilePath}. Resolve any relative file references from ${instructionsFileDir}.`;
352→      const combinedPath = path.join(skillsDir, "agent-instructions.md");
353→      await fs.writeFile(combinedPath, instructionsContent + pathDirective, "utf-8");
354→      effectiveInstructionsFilePath = combinedPath;
355→      await onLog("stderr", `[paperclip] Loaded agent instructions file: ${instructionsFilePath}\n`);
356→    } catch (err) {
357→      const reason = err instanceof Error ? err.message : String(err);
358→      await onLog(
359→        "stderr",
360→        `[paperclip] Warning: could not read agent instructions file "${instructionsFilePath}": ${reason}\n`,
361→      );
362→      effectiveInstructionsFilePath = undefined;
363→    }
364→  }
365→
366→  const runtimeSessionParams = parseObject(runtime.sessionParams);
367→  const runtimeSessionId = asString(runtimeSessionParams.sessionId, runtime.sessionId ?? "");
368→  const runtimeSessionCwd = asString(runtimeSessionParams.cwd, "");
369→  const canResumeSession =
370→    runtimeSessionId.length > 0 &&
371→    (runtimeSessionCwd.length === 0 || path.resolve(runtimeSessionCwd) === path.resolve(cwd));
372→  const sessionId = canResumeSession ? runtimeSessionId : null;
373→  if (runtimeSessionId && !canResumeSession) {
374→    await onLog(
375→      "stdout",
376→      `[paperclip] Claude session "${runtimeSessionId}" was saved for cwd "${runtimeSessionCwd}" and will not be resumed in "${cwd}".\n`,
377→    );
378→  }
379→  const bootstrapPromptTemplate = asString(config.bootstrapPromptTemplate, "");
380→  const templateData = {
381→    agentId: agent.id,
382→    companyId: agent.companyId,
383→    runId,
384→    company: { id: agent.companyId },
385→    agent,
386→    run: { id: runId, source: "on_demand" },
387→    context,
388→  };
389→  const renderedPrompt = renderTemplate(promptTemplate, templateData);
390→  const renderedBootstrapPrompt =
391→    !sessionId && bootstrapPromptTemplate.trim().length > 0
392→      ? renderTemplate(bootstrapPromptTemplate, templateData).trim()
393→      : "";
394→  const sessionHandoffNote = asString(context.paperclipSessionHandoffMarkdown, "").trim();
395→  const prompt = joinPromptSections([
396→    renderedBootstrapPrompt,
397→    sessionHandoffNote,
398→    renderedPrompt,
399→  ]);
400→  const promptMetrics = {
401→    promptChars: prompt.length,
402→    bootstrapPromptChars: renderedBootstrapPrompt.length,
403→    sessionHandoffChars: sessionHandoffNote.length,
404→    heartbeatPromptChars: renderedPrompt.length,
405→  };
406→
407→  const buildClaudeArgs = (resumeSessionId: string | null) => {
408→    const args = ["--print", "-", "--output-format", "stream-json", "--verbose"];
409→    if (resumeSessionId) args.push("--resume", resumeSessionId);
410→    if (dangerouslySkipPermissions) args.push("--dangerously-skip-permissions");
411→    if (chrome) args.push("--chrome");
412→    if (model) args.push("--model", model);
413→    if (effort) args.push("--effort", effort);
414→    if (maxTurns > 0) args.push("--max-turns", String(maxTurns));
415→    if (effectiveInstructionsFilePath) {
416→      args.push("--append-system-prompt-file", effectiveInstructionsFilePath);
417→    }
418→    args.push("--add-dir", skillsDir);
419→    if (extraArgs.length > 0) args.push(...extraArgs);
420→    return args;
421→  };
422→
423→  const parseFallbackErrorMessage = (proc: RunProcessResult) => {
424→    const stderrLine =
425→      proc.stderr
426→        .split(/\r?\n/)
427→        .map((line) => line.trim())
428→        .find(Boolean) ?? "";
429→
430→    if ((proc.exitCode ?? 0) === 0) {
431→      return "Failed to parse claude JSON output";
432→    }
433→
434→    return stderrLine
435→      ? `Claude exited with code ${proc.exitCode ?? -1}: ${stderrLine}`
436→      : `Claude exited with code ${proc.exitCode ?? -1}`;
437→  };
438→
439→  const runAttempt = async (resumeSessionId: string | null) => {
440→    const args = buildClaudeArgs(resumeSessionId);
441→    if (onMeta) {
442→      await onMeta({
443→        adapterType: "claude_local",
444→        command,
445→        cwd,
446→        commandArgs: args,
447→        commandNotes,
448→        env: redactEnvForLogs(env),
449→        prompt,
450→        promptMetrics,
451→        context,
452→      });
453→    }
454→
455→    const proc = await runChildProcess(runId, command, args, {
456→      cwd,
457→      env,
458→      stdin: prompt,
459→      timeoutSec,
460→      graceSec,
461→      onSpawn,
462→      onLog,
463→    });
464→
465→    const parsedStream = parseClaudeStreamJson(proc.stdout);
466→    const parsed = parsedStream.resultJson ?? parseJson(proc.stdout);
467→    return { proc, parsedStream, parsed };
468→  };
469→
470→  const toAdapterResult = (
471→    attempt: {
472→      proc: RunProcessResult;
473→      parsedStream: ReturnType<typeof parseClaudeStreamJson>;
474→      parsed: Record<string, unknown> | null;
475→    },
476→    opts: { fallbackSessionId: string | null; clearSessionOnMissingSession?: boolean },
477→  ): AdapterExecutionResult => {
478→    const { proc, parsedStream, parsed } = attempt;
479→    const loginMeta = detectClaudeLoginRequired({
480→      parsed,
481→      stdout: proc.stdout,
482→      stderr: proc.stderr,
483→    });
484→    const errorMeta =
485→      loginMeta.loginUrl != null
486→        ? {
487→            loginUrl: loginMeta.loginUrl,
488→          }
489→        : undefined;
490→
491→    if (proc.timedOut) {
492→      return {
493→        exitCode: proc.exitCode,
494→        signal: proc.signal,
495→        timedOut: true,
496→        errorMessage: `Timed out after ${timeoutSec}s`,
497→        errorCode: "timeout",
498→        errorMeta,
499→        clearSession: Boolean(opts.clearSessionOnMissingSession),
500→      };
501→    }
502→
503→    if (!parsed) {
504→      return {
505→        exitCode: proc.exitCode,
506→        signal: proc.signal,
507→        timedOut: false,
508→        errorMessage: parseFallbackErrorMessage(proc),
509→        errorCode: loginMeta.requiresLogin ? "claude_auth_required" : null,
510→        errorMeta,
511→        resultJson: {
512→          stdout: proc.stdout,
513→          stderr: proc.stderr,
514→        },
515→        clearSession: Boolean(opts.clearSessionOnMissingSession),
516→      };
517→    }
518→
519→    const usage =
520→      parsedStream.usage ??
521→      (() => {
522→        const usageObj = parseObject(parsed.usage);
523→        return {
524→          inputTokens: asNumber(usageObj.input_tokens, 0),
525→          cachedInputTokens: asNumber(usageObj.cache_read_input_tokens, 0),
526→          outputTokens: asNumber(usageObj.output_tokens, 0),
527→        };
528→      })();
529→
530→    const resolvedSessionId =
531→      parsedStream.sessionId ??
532→      (asString(parsed.session_id, opts.fallbackSessionId ?? "") || opts.fallbackSessionId);
533→    const resolvedSessionParams = resolvedSessionId
534→      ? ({
535→        sessionId: resolvedSessionId,
536→        cwd,
537→        ...(workspaceId ? { workspaceId } : {}),
538→        ...(workspaceRepoUrl ? { repoUrl: workspaceRepoUrl } : {}),
539→        ...(workspaceRepoRef ? { repoRef: workspaceRepoRef } : {}),
540→      } as Record<string, unknown>)
541→      : null;
542→    const clearSessionForMaxTurns = isClaudeMaxTurnsResult(parsed);
543→
544→    return {
545→      exitCode: proc.exitCode,
546→      signal: proc.signal,
547→      timedOut: false,
548→      errorMessage:
549→        (proc.exitCode ?? 0) === 0
550→          ? null
551→          : describeClaudeFailure(parsed) ?? `Claude exited with code ${proc.exitCode ?? -1}`,
552→      errorCode: loginMeta.requiresLogin ? "claude_auth_required" : null,
553→      errorMeta,
554→      usage,
555→      sessionId: resolvedSessionId,
556→      sessionParams: resolvedSessionParams,
557→      sessionDisplayId: resolvedSessionId,
558→      provider: "anthropic",
559→      biller: "anthropic",
560→      model: parsedStream.model || asString(parsed.model, model),
561→      billingType,
562→      costUsd: parsedStream.costUsd ?? asNumber(parsed.total_cost_usd, 0),
563→      resultJson: parsed,
564→      summary: parsedStream.summary || asString(parsed.result, ""),
565→      clearSession: clearSessionForMaxTurns || Boolean(opts.clearSessionOnMissingSession && !resolvedSessionId),
566→    };
567→  };
568→
569→  try {
570→    const initial = await runAttempt(sessionId ?? null);
571→    if (
572→      sessionId &&
573→      !initial.proc.timedOut &&
574→      (initial.proc.exitCode ?? 0) !== 0 &&
575→      initial.parsed &&
576→      isClaudeUnknownSessionError(initial.parsed)
577→    ) {
578→      await onLog(
579→        "stdout",
580→        `[paperclip] Claude resume session "${sessionId}" is unavailable; retrying with a fresh session.\n`,
581→      );
582→      const retry = await runAttempt(null);
583→      return toAdapterResult(retry, { fallbackSessionId: null, clearSessionOnMissingSession: true });
584→    }
585→
586→    return toAdapterResult(initial, { fallbackSessionId: runtimeSessionId || runtime.sessionId });
587→  } finally {
588→    fs.rm(skillsDir, { recursive: true, force: true }).catch(() => {});
589→  }
590→}
