 86→function stableStringify(value: unknown): string {
 87→  if (Array.isArray(value)) {
 88→    return `[${value.map((entry) => stableStringify(entry)).join(",")}]`;
 89→  }
 90→  if (value && typeof value === "object") {
 91→    const rec = value as Record<string, unknown>;
 92→    return `{${Object.keys(rec).sort().map((key) => `${JSON.stringify(key)}:${stableStringify(rec[key])}`).join(",")}}`;
 93→  }
 94→  return JSON.stringify(value);
 95→}
