231→async function executeProcess(input: {
232→  command: string;
233→  args: string[];
234→  cwd: string;
235→  env?: NodeJS.ProcessEnv;
236→}): Promise<{ stdout: string; stderr: string; code: number | null }> {
237→  const proc = await new Promise<{ stdout: string; stderr: string; code: number | null }>((resolve, reject) => {
238→    const child = spawn(input.command, input.args, {
239→      cwd: input.cwd,
240→      stdio: ["ignore", "pipe", "pipe"],
241→      env: input.env ?? process.env,
242→    });
243→    let stdout = "";
244→    let stderr = "";
245→    child.stdout?.on("data", (chunk) => {
246→      stdout += String(chunk);
247→    });
248→    child.stderr?.on("data", (chunk) => {
249→      stderr += String(chunk);
250→    });
251→    child.on("error", reject);
252→    child.on("close", (code) => resolve({ stdout, stderr, code }));
253→  });
254→  return proc;
255→}
