257→async function runGit(args: string[], cwd: string): Promise<string> {
258→  const proc = await executeProcess({
259→    command: "git",
260→    args,
261→    cwd,
262→  });
263→  if (proc.code !== 0) {
264→    throw new Error(proc.stderr.trim() || proc.stdout.trim() || `git ${args.join(" ")} failed`);
265→  }
266→  return proc.stdout.trim();
267→}
