278→function terminateChildProcess(child: ChildProcess) {
279→  if (!child.pid) return;
280→  if (process.platform !== "win32") {
281→    try {
282→      process.kill(-child.pid, "SIGTERM");
283→      return;
284→    } catch {
285→      // Fall through to the direct child kill.
286→    }
287→  }
288→  if (!child.killed) {
289→    child.kill("SIGTERM");
290→  }
291→}
