324→async function runWorkspaceCommand(input: {
325→  command: string;
326→  cwd: string;
327→  env: NodeJS.ProcessEnv;
328→  label: string;
329→}) {
330→  const shell = process.env.SHELL?.trim() || "/bin/sh";
331→  const proc = await executeProcess({
332→    command: shell,
333→    args: ["-c", input.command],
334→    cwd: input.cwd,
335→    env: input.env,
336→  });
337→  if (proc.code === 0) return;
338→
339→  const details = [proc.stderr.trim(), proc.stdout.trim()].filter(Boolean).join("\n");
340→  throw new Error(
341→    details.length > 0
342→      ? `${input.label} failed: ${details}`
343→      : `${input.label} failed with exit code ${proc.code ?? -1}`,
344→  );
345→}
