347→async function recordGitOperation(
348→  recorder: WorkspaceOperationRecorder | null | undefined,
349→  input: {
350→    phase: "worktree_prepare" | "worktree_cleanup";
351→    args: string[];
352→    cwd: string;
353→    metadata?: Record<string, unknown> | null;
354→    successMessage?: string | null;
355→    failureLabel?: string | null;
356→  },
357→): Promise<string> {
358→  if (!recorder) {
359→    return runGit(input.args, input.cwd);
360→  }
361→
362→  let stdout = "";
363→  let stderr = "";
364→  let code: number | null = null;
365→  await recorder.recordOperation({
366→    phase: input.phase,
367→    command: formatCommandForDisplay("git", input.args),
368→    cwd: input.cwd,
369→    metadata: input.metadata ?? null,
370→    run: async () => {
371→      const result = await executeProcess({
372→        command: "git",
373→        args: input.args,
374→        cwd: input.cwd,
375→      });
376→      stdout = result.stdout;
377→      stderr = result.stderr;
378→      code = result.code;
379→      return {
380→        status: result.code === 0 ? "succeeded" : "failed",
381→        exitCode: result.code,
382→        stdout: result.stdout,
383→        stderr: result.stderr,
384→        system: result.code === 0 ? input.successMessage ?? null : null,
385→      };
386→    },
387→  });
388→
389→  if (code !== 0) {
390→    const details = [stderr.trim(), stdout.trim()].filter(Boolean).join("\n");
391→    throw new Error(
392→      details.length > 0
393→        ? `${input.failureLabel ?? `git ${input.args.join(" ")}`} failed: ${details}`
394→        : `${input.failureLabel ?? `git ${input.args.join(" ")}`} failed with exit code ${code ?? -1}`,
395→    );
396→  }
397→  return stdout.trim();
398→}
