171→export function buildExecutionWorkspaceAdapterConfig(input: {
172→  agentConfig: Record<string, unknown>;
173→  projectPolicy: ProjectExecutionWorkspacePolicy | null;
174→  issueSettings: IssueExecutionWorkspaceSettings | null;
175→  mode: ParsedExecutionWorkspaceMode;
176→  legacyUseProjectWorkspace: boolean | null;
177→}): Record<string, unknown> {
178→  const nextConfig = { ...input.agentConfig };
179→  const projectHasPolicy = Boolean(input.projectPolicy?.enabled);
180→  const issueHasWorkspaceOverrides = Boolean(
181→    input.issueSettings?.mode ||
182→    input.issueSettings?.workspaceStrategy ||
183→    input.issueSettings?.workspaceRuntime,
184→  );
185→  const hasWorkspaceControl = projectHasPolicy || issueHasWorkspaceOverrides || input.legacyUseProjectWorkspace === false;
186→
187→  if (hasWorkspaceControl) {
188→    if (input.mode === "isolated_workspace") {
189→      const strategy =
190→        input.issueSettings?.workspaceStrategy ??
191→        input.projectPolicy?.workspaceStrategy ??
192→        parseExecutionWorkspaceStrategy(nextConfig.workspaceStrategy) ??
193→        ({ type: "git_worktree" } satisfies ExecutionWorkspaceStrategy);
194→      nextConfig.workspaceStrategy = strategy as unknown as Record<string, unknown>;
195→    } else {
196→      delete nextConfig.workspaceStrategy;
197→    }
198→
199→    if (input.mode === "agent_default") {
200→      delete nextConfig.workspaceRuntime;
201→    } else if (input.issueSettings?.workspaceRuntime) {
202→      nextConfig.workspaceRuntime = cloneRecord(input.issueSettings.workspaceRuntime) ?? undefined;
203→    } else if (input.projectPolicy?.workspaceRuntime) {
204→      nextConfig.workspaceRuntime = cloneRecord(input.projectPolicy.workspaceRuntime) ?? undefined;
205→    }
206→  }
207→
208→  return nextConfig;
209→}
