 1→import os from "node:os";
 2→import path from "node:path";
 3→
 4→const DEFAULT_INSTANCE_ID = "default";
 5→const INSTANCE_ID_RE = /^[a-zA-Z0-9_-]+$/;
 6→const PATH_SEGMENT_RE = /^[a-zA-Z0-9_-]+$/;
 7→const FRIENDLY_PATH_SEGMENT_RE = /[^a-zA-Z0-9._-]+/g;
 8→
 9→function expandHomePrefix(value: string): string {
10→  if (value === "~") return os.homedir();
11→  if (value.startsWith("~/")) return path.resolve(os.homedir(), value.slice(2));
12→  return value;
13→}
14→
15→export function resolvePaperclipHomeDir(): string {
16→  const envHome = process.env.PAPERCLIP_HOME?.trim();
17→  if (envHome) return path.resolve(expandHomePrefix(envHome));
18→  return path.resolve(os.homedir(), ".paperclip");
19→}
20→
21→export function resolvePaperclipInstanceId(): string {
22→  const raw = process.env.PAPERCLIP_INSTANCE_ID?.trim() || DEFAULT_INSTANCE_ID;
23→  if (!INSTANCE_ID_RE.test(raw)) {
24→    throw new Error(`Invalid PAPERCLIP_INSTANCE_ID '${raw}'.`);
25→  }
26→  return raw;
27→}
28→
29→export function resolvePaperclipInstanceRoot(): string {
30→  return path.resolve(resolvePaperclipHomeDir(), "instances", resolvePaperclipInstanceId());
31→}
32→
33→export function resolveDefaultConfigPath(): string {
34→  return path.resolve(resolvePaperclipInstanceRoot(), "config.json");
35→}
36→
37→export function resolveDefaultEmbeddedPostgresDir(): string {
38→  return path.resolve(resolvePaperclipInstanceRoot(), "db");
39→}
40→
41→export function resolveDefaultLogsDir(): string {
42→  return path.resolve(resolvePaperclipInstanceRoot(), "logs");
43→}
44→
45→export function resolveDefaultSecretsKeyFilePath(): string {
46→  return path.resolve(resolvePaperclipInstanceRoot(), "secrets", "master.key");
47→}
48→
49→export function resolveDefaultStorageDir(): string {
50→  return path.resolve(resolvePaperclipInstanceRoot(), "data", "storage");
51→}
52→
53→export function resolveDefaultBackupDir(): string {
54→  return path.resolve(resolvePaperclipInstanceRoot(), "data", "backups");
55→}
56→
57→export function resolveDefaultAgentWorkspaceDir(agentId: string): string {
58→  const trimmed = agentId.trim();
59→  if (!PATH_SEGMENT_RE.test(trimmed)) {
60→    throw new Error(`Invalid agent id for workspace path '${agentId}'.`);
61→  }
62→  return path.resolve(resolvePaperclipInstanceRoot(), "workspaces", trimmed);
63→}
64→
65→function sanitizeFriendlyPathSegment(value: string | null | undefined, fallback = "_default"): string {
66→  const trimmed = value?.trim() ?? "";
67→  if (!trimmed) return fallback;
68→  const sanitized = trimmed
69→    .replace(FRIENDLY_PATH_SEGMENT_RE, "-")
70→    .replace(/^-+|-+$/g, "");
71→  return sanitized || fallback;
72→}
73→
74→export function resolveManagedProjectWorkspaceDir(input: {
75→  companyId: string;
76→  projectId: string;
77→  repoName?: string | null;
78→}): string {
79→  const companyId = input.companyId.trim();
80→  const projectId = input.projectId.trim();
81→  if (!companyId || !projectId) {
82→    throw new Error("Managed project workspace path requires companyId and projectId.");
83→  }
84→  return path.resolve(
85→    resolvePaperclipInstanceRoot(),
86→    "projects",
87→    sanitizeFriendlyPathSegment(companyId, "company"),
88→    sanitizeFriendlyPathSegment(projectId, "project"),
89→    sanitizeFriendlyPathSegment(input.repoName, "_default"),
90→  );
91→}
92→
93→export function resolveHomeAwarePath(value: string): string {
94→  return path.resolve(expandHomePrefix(value));
95→}
