  1→import fs from "node:fs/promises";
  2→import path from "node:path";
  3→import { notFound, unprocessable } from "../errors.js";
  4→import { resolveHomeAwarePath, resolvePaperclipInstanceRoot } from "../home-paths.js";
  5→
  6→const ENTRY_FILE_DEFAULT = "AGENTS.md";
  7→const MODE_KEY = "instructionsBundleMode";
  8→const ROOT_KEY = "instructionsRootPath";
  9→const ENTRY_KEY = "instructionsEntryFile";
 10→const FILE_KEY = "instructionsFilePath";
 11→const PROMPT_KEY = "promptTemplate";
 12→const BOOTSTRAP_PROMPT_KEY = "bootstrapPromptTemplate";
 13→const LEGACY_PROMPT_TEMPLATE_PATH = "promptTemplate.legacy.md";
 14→const IGNORED_INSTRUCTIONS_FILE_NAMES = new Set([".DS_Store", "Thumbs.db", "Desktop.ini"]);
 15→const IGNORED_INSTRUCTIONS_DIRECTORY_NAMES = new Set([
 16→  ".git",
 17→  ".nox",
 18→  ".pytest_cache",
 19→  ".ruff_cache",
 20→  ".tox",
 21→  ".venv",
 22→  "__pycache__",
 23→  "node_modules",
 24→  "venv",
 25→]);
 26→
 27→type BundleMode = "managed" | "external";
 28→
 29→type AgentLike = {
 30→  id: string;
 31→  companyId: string;
 32→  name: string;
 33→  adapterConfig: unknown;
 34→};
 35→
 36→type AgentInstructionsFileSummary = {
 37→  path: string;
 38→  size: number;
 39→  language: string;
 40→  markdown: boolean;
 41→  isEntryFile: boolean;
 42→  editable: boolean;
 43→  deprecated: boolean;
 44→  virtual: boolean;
 45→};
 46→
 47→type AgentInstructionsFileDetail = AgentInstructionsFileSummary & {
 48→  content: string;
 49→  editable: boolean;
 50→};
 51→
 52→type AgentInstructionsBundle = {
 53→  agentId: string;
 54→  companyId: string;
 55→  mode: BundleMode | null;
 56→  rootPath: string | null;
 57→  managedRootPath: string;
 58→  entryFile: string;
 59→  resolvedEntryPath: string | null;
 60→  editable: boolean;
 61→  warnings: string[];
 62→  legacyPromptTemplateActive: boolean;
 63→  legacyBootstrapPromptTemplateActive: boolean;
 64→  files: AgentInstructionsFileSummary[];
 65→};
 66→
 67→type BundleState = {
 68→  config: Record<string, unknown>;
 69→  mode: BundleMode | null;
 70→  rootPath: string | null;
 71→  entryFile: string;
 72→  resolvedEntryPath: string | null;
 73→  warnings: string[];
 74→  legacyPromptTemplateActive: boolean;
 75→  legacyBootstrapPromptTemplateActive: boolean;
 76→};
 77→
 78→function asRecord(value: unknown): Record<string, unknown> {
 79→  if (typeof value !== "object" || value === null || Array.isArray(value)) return {};
 80→  return value as Record<string, unknown>;
 81→}
 82→
 83→function asString(value: unknown): string | null {
 84→  if (typeof value !== "string") return null;
 85→  const trimmed = value.trim();
 86→  return trimmed.length > 0 ? trimmed : null;
 87→}
 88→
 89→function isBundleMode(value: unknown): value is BundleMode {
 90→  return value === "managed" || value === "external";
 91→}
 92→
 93→function inferLanguage(relativePath: string): string {
 94→  const lower = relativePath.toLowerCase();
 95→  if (lower.endsWith(".md")) return "markdown";
 96→  if (lower.endsWith(".json")) return "json";
 97→  if (lower.endsWith(".yaml") || lower.endsWith(".yml")) return "yaml";
 98→  if (lower.endsWith(".ts") || lower.endsWith(".tsx")) return "typescript";
 99→  if (lower.endsWith(".js") || lower.endsWith(".jsx") || lower.endsWith(".mjs") || lower.endsWith(".cjs")) {
100→    return "javascript";
101→  }
102→  if (lower.endsWith(".sh")) return "bash";
103→  if (lower.endsWith(".py")) return "python";
104→  if (lower.endsWith(".toml")) return "toml";
105→  if (lower.endsWith(".txt")) return "text";
106→  return "text";
107→}
108→
109→function isMarkdown(relativePath: string) {
110→  return relativePath.toLowerCase().endsWith(".md");
111→}
112→
113→function normalizeRelativeFilePath(candidatePath: string): string {
114→  const normalized = path.posix.normalize(candidatePath.replaceAll("\\", "/")).replace(/^\/+/, "");
115→  if (!normalized || normalized === "." || normalized === ".." || normalized.startsWith("../")) {
116→    throw unprocessable("Instructions file path must stay within the bundle root");
117→  }
118→  return normalized;
119→}
120→
121→function resolvePathWithinRoot(rootPath: string, relativePath: string): string {
122→  const normalizedRelativePath = normalizeRelativeFilePath(relativePath);
123→  const absoluteRoot = path.resolve(rootPath);
124→  const absolutePath = path.resolve(absoluteRoot, normalizedRelativePath);
125→  const relativeToRoot = path.relative(absoluteRoot, absolutePath);
126→  if (relativeToRoot === ".." || relativeToRoot.startsWith(`..${path.sep}`)) {
127→    throw unprocessable("Instructions file path must stay within the bundle root");
128→  }
129→  return absolutePath;
130→}
131→
132→function resolveManagedInstructionsRoot(agent: AgentLike): string {
133→  return path.resolve(
134→    resolvePaperclipInstanceRoot(),
135→    "companies",
136→    agent.companyId,
137→    "agents",
138→    agent.id,
139→    "instructions",
140→  );
141→}
142→
143→function resolveLegacyInstructionsPath(candidatePath: string, config: Record<string, unknown>): string {
144→  if (path.isAbsolute(candidatePath)) return candidatePath;
145→  const cwd = asString(config.cwd);
146→  if (!cwd || !path.isAbsolute(cwd)) {
147→    throw unprocessable(
148→      "Legacy relative instructionsFilePath requires adapterConfig.cwd to be set to an absolute path",
149→    );
150→  }
151→  return path.resolve(cwd, candidatePath);
152→}
153→
154→async function statIfExists(targetPath: string) {
155→  return fs.stat(targetPath).catch(() => null);
156→}
157→
158→function shouldIgnoreInstructionsEntry(entry: { name: string; isDirectory(): boolean; isFile(): boolean }) {
159→  if (entry.name === "." || entry.name === "..") return true;
160→  if (entry.isDirectory()) {
161→    return IGNORED_INSTRUCTIONS_DIRECTORY_NAMES.has(entry.name);
162→  }
163→  if (!entry.isFile()) return false;
164→  return (
165→    IGNORED_INSTRUCTIONS_FILE_NAMES.has(entry.name)
166→    || entry.name.startsWith("._")
167→    || entry.name.endsWith(".pyc")
168→    || entry.name.endsWith(".pyo")
169→  );
170→}
171→
172→async function listFilesRecursive(rootPath: string): Promise<string[]> {
173→  const output: string[] = [];
174→
175→  async function walk(currentPath: string, relativeDir: string) {
176→    const entries = await fs.readdir(currentPath, { withFileTypes: true }).catch(() => []);
177→    for (const entry of entries) {
178→      if (shouldIgnoreInstructionsEntry(entry)) continue;
179→      const absolutePath = path.join(currentPath, entry.name);
180→      const relativePath = normalizeRelativeFilePath(
181→        relativeDir ? path.posix.join(relativeDir, entry.name) : entry.name,
182→      );
183→      if (entry.isDirectory()) {
184→        await walk(absolutePath, relativePath);
185→        continue;
186→      }
187→      if (!entry.isFile()) continue;
188→      output.push(relativePath);
189→    }
190→  }
191→
192→  await walk(rootPath, "");
193→  return output.sort((left, right) => left.localeCompare(right));
194→}
195→
196→async function readFileSummary(rootPath: string, relativePath: string, entryFile: string): Promise<AgentInstructionsFileSummary> {
197→  const absolutePath = resolvePathWithinRoot(rootPath, relativePath);
198→  const stat = await fs.stat(absolutePath);
199→  return {
200→    path: relativePath,
201→    size: stat.size,
202→    language: inferLanguage(relativePath),
203→    markdown: isMarkdown(relativePath),
204→    isEntryFile: relativePath === entryFile,
205→    editable: true,
206→    deprecated: false,
207→    virtual: false,
208→  };
209→}
210→
211→async function readLegacyInstructions(agent: AgentLike, config: Record<string, unknown>): Promise<string> {
212→  const instructionsFilePath = asString(config[FILE_KEY]);
213→  if (instructionsFilePath) {
214→    try {
215→      const resolvedPath = resolveLegacyInstructionsPath(instructionsFilePath, config);
216→      return await fs.readFile(resolvedPath, "utf8");
217→    } catch {
218→      // Fall back to promptTemplate below.
219→    }
220→  }
221→  return asString(config[PROMPT_KEY]) ?? "";
222→}
223→
224→function deriveBundleState(agent: AgentLike): BundleState {
225→  const config = asRecord(agent.adapterConfig);
226→  const warnings: string[] = [];
227→  const storedModeRaw = config[MODE_KEY];
228→  const storedRootRaw = asString(config[ROOT_KEY]);
229→  const legacyInstructionsPath = asString(config[FILE_KEY]);
230→
231→  let mode: BundleMode | null = isBundleMode(storedModeRaw) ? storedModeRaw : null;
232→  let rootPath = storedRootRaw ? resolveHomeAwarePath(storedRootRaw) : null;
233→  let entryFile = ENTRY_FILE_DEFAULT;
234→
235→  const storedEntryRaw = asString(config[ENTRY_KEY]);
236→  if (storedEntryRaw) {
237→    try {
238→      entryFile = normalizeRelativeFilePath(storedEntryRaw);
239→    } catch {
240→      warnings.push(`Ignored invalid instructions entry file "${storedEntryRaw}".`);
241→    }
242→  }
243→
244→  if (!rootPath && legacyInstructionsPath) {
245→    try {
246→      const resolvedLegacyPath = resolveLegacyInstructionsPath(legacyInstructionsPath, config);
247→      rootPath = path.dirname(resolvedLegacyPath);
248→      entryFile = path.basename(resolvedLegacyPath);
249→      mode = resolvedLegacyPath.startsWith(`${resolveManagedInstructionsRoot(agent)}${path.sep}`)
250→        || resolvedLegacyPath === path.join(resolveManagedInstructionsRoot(agent), entryFile)
251→        ? "managed"
252→        : "external";
253→      if (!path.isAbsolute(legacyInstructionsPath)) {
254→        warnings.push("Using legacy relative instructionsFilePath; migrate this agent to a managed or absolute external bundle.");
255→      }
256→    } catch (err) {
257→      warnings.push(err instanceof Error ? err.message : String(err));
258→    }
259→  }
260→
261→  const resolvedEntryPath = rootPath ? path.resolve(rootPath, entryFile) : null;
262→
263→  return {
264→    config,
265→    mode,
266→    rootPath,
267→    entryFile,
268→    resolvedEntryPath,
269→    warnings,
270→    legacyPromptTemplateActive: Boolean(asString(config[PROMPT_KEY])),
271→    legacyBootstrapPromptTemplateActive: Boolean(asString(config[BOOTSTRAP_PROMPT_KEY])),
272→  };
273→}
274→
275→async function recoverManagedBundleState(agent: AgentLike, state: BundleState): Promise<BundleState> {
276→  const managedRootPath = resolveManagedInstructionsRoot(agent);
277→  const stat = await statIfExists(managedRootPath);
278→  if (!stat?.isDirectory()) return state;
279→
280→  const files = await listFilesRecursive(managedRootPath);
281→  if (files.length === 0) return state;
282→
283→  const recoveredEntryFile = files.includes(state.entryFile)
284→    ? state.entryFile
285→    : files.includes(ENTRY_FILE_DEFAULT)
286→      ? ENTRY_FILE_DEFAULT
287→      : files[0]!;
288→
289→  if (!state.rootPath) {
290→    return {
291→      ...state,
292→      mode: "managed",
293→      rootPath: managedRootPath,
294→      entryFile: recoveredEntryFile,
295→      resolvedEntryPath: path.resolve(managedRootPath, recoveredEntryFile),
296→    };
297→  }
298→
299→  if (state.mode === "external") return state;
300→
301→  const resolvedConfiguredRoot = path.resolve(state.rootPath);
302→  const configuredRootMatchesManaged = resolvedConfiguredRoot === managedRootPath;
303→  const hasEntryMismatch = recoveredEntryFile !== state.entryFile;
304→
305→  if (configuredRootMatchesManaged && !hasEntryMismatch) {
306→    return state;
307→  }
308→
309→  const warnings = [...state.warnings];
310→  if (!configuredRootMatchesManaged) {
311→    warnings.push(
312→      `Recovered managed instructions from disk at ${managedRootPath}; ignoring stale configured root ${state.rootPath}.`,
313→    );
314→  }
315→  if (hasEntryMismatch) {
316→    warnings.push(
317→      `Recovered managed instructions entry file from disk as ${recoveredEntryFile}; previous entry ${state.entryFile} was missing.`,
318→    );
319→  }
320→
321→  return {
322→    ...state,
323→    mode: "managed",
324→    rootPath: managedRootPath,
325→    entryFile: recoveredEntryFile,
326→    resolvedEntryPath: path.resolve(managedRootPath, recoveredEntryFile),
327→    warnings,
328→  };
329→}
330→
331→function toBundle(agent: AgentLike, state: BundleState, files: AgentInstructionsFileSummary[]): AgentInstructionsBundle {
332→  const nextFiles = [...files];
333→  if (state.legacyPromptTemplateActive && !nextFiles.some((file) => file.path === LEGACY_PROMPT_TEMPLATE_PATH)) {
334→    const legacyPromptTemplate = asString(state.config[PROMPT_KEY]) ?? "";
335→    nextFiles.push({
336→      path: LEGACY_PROMPT_TEMPLATE_PATH,
337→      size: legacyPromptTemplate.length,
338→      language: "markdown",
339→      markdown: true,
340→      isEntryFile: false,
341→      editable: true,
342→      deprecated: true,
343→      virtual: true,
344→    });
345→  }
346→  nextFiles.sort((left, right) => left.path.localeCompare(right.path));
347→  return {
348→    agentId: agent.id,
349→    companyId: agent.companyId,
350→    mode: state.mode,
351→    rootPath: state.rootPath,
352→    managedRootPath: resolveManagedInstructionsRoot(agent),
353→    entryFile: state.entryFile,
354→    resolvedEntryPath: state.resolvedEntryPath,
355→    editable: Boolean(state.rootPath),
356→    warnings: state.warnings,
357→    legacyPromptTemplateActive: state.legacyPromptTemplateActive,
358→    legacyBootstrapPromptTemplateActive: state.legacyBootstrapPromptTemplateActive,
359→    files: nextFiles,
360→  };
361→}
362→
363→function applyBundleConfig(
364→  config: Record<string, unknown>,
365→  input: {
366→    mode: BundleMode;
367→    rootPath: string;
368→    entryFile: string;
369→    clearLegacyPromptTemplate?: boolean;
370→  },
371→): Record<string, unknown> {
372→  const next: Record<string, unknown> = {
373→    ...config,
374→    [MODE_KEY]: input.mode,
375→    [ROOT_KEY]: input.rootPath,
376→    [ENTRY_KEY]: input.entryFile,
377→    [FILE_KEY]: path.resolve(input.rootPath, input.entryFile),
378→  };
379→  if (input.clearLegacyPromptTemplate) {
380→    delete next[PROMPT_KEY];
381→    delete next[BOOTSTRAP_PROMPT_KEY];
382→  }
383→  return next;
384→}
385→
386→function buildPersistedBundleConfig(
387→  derived: BundleState,
388→  current: BundleState,
389→  options?: { clearLegacyPromptTemplate?: boolean },
390→): Record<string, unknown> {
391→  const currentRootPath = current.rootPath ? path.resolve(current.rootPath) : null;
392→  const derivedRootPath = derived.rootPath ? path.resolve(derived.rootPath) : null;
393→  const configMatchesRecoveredState =
394→    derived.mode === current.mode
395→    && derivedRootPath !== null
396→    && currentRootPath !== null
397→    && derivedRootPath === currentRootPath
398→    && derived.entryFile === current.entryFile;
399→
400→  if (configMatchesRecoveredState && !options?.clearLegacyPromptTemplate) {
401→    return current.config;
402→  }
403→
404→  if (!current.rootPath || !current.mode) {
405→    return current.config;
406→  }
407→
408→  return applyBundleConfig(current.config, {
409→    mode: current.mode,
410→    rootPath: current.rootPath,
411→    entryFile: current.entryFile,
412→    clearLegacyPromptTemplate: options?.clearLegacyPromptTemplate,
413→  });
414→}
415→
416→async function writeBundleFiles(
417→  rootPath: string,
418→  files: Record<string, string>,
419→  options?: { overwriteExisting?: boolean },
420→) {
421→  for (const [relativePath, content] of Object.entries(files)) {
422→    const normalizedPath = normalizeRelativeFilePath(relativePath);
423→    const absolutePath = resolvePathWithinRoot(rootPath, normalizedPath);
424→    const existingStat = await statIfExists(absolutePath);
425→    if (existingStat?.isFile() && !options?.overwriteExisting) continue;
426→    await fs.mkdir(path.dirname(absolutePath), { recursive: true });
427→    await fs.writeFile(absolutePath, content, "utf8");
428→  }
429→}
430→
431→export function syncInstructionsBundleConfigFromFilePath(
432→  agent: AgentLike,
433→  adapterConfig: Record<string, unknown>,
434→): Record<string, unknown> {
435→  const instructionsFilePath = asString(adapterConfig[FILE_KEY]);
436→  const next = { ...adapterConfig };
437→  if (!instructionsFilePath) {
438→    delete next[MODE_KEY];
439→    delete next[ROOT_KEY];
440→    delete next[ENTRY_KEY];
441→    return next;
442→  }
443→  const resolvedPath = resolveLegacyInstructionsPath(instructionsFilePath, adapterConfig);
444→  const rootPath = path.dirname(resolvedPath);
445→  const entryFile = path.basename(resolvedPath);
446→  const mode: BundleMode = resolvedPath.startsWith(`${resolveManagedInstructionsRoot(agent)}${path.sep}`)
447→    || resolvedPath === path.join(resolveManagedInstructionsRoot(agent), entryFile)
448→    ? "managed"
449→    : "external";
450→  return applyBundleConfig(next, { mode, rootPath, entryFile });
451→}
452→
453→export function agentInstructionsService() {
454→  async function getBundle(agent: AgentLike): Promise<AgentInstructionsBundle> {
455→    const state = await recoverManagedBundleState(agent, deriveBundleState(agent));
456→    if (!state.rootPath) return toBundle(agent, state, []);
457→    const stat = await statIfExists(state.rootPath);
458→    if (!stat?.isDirectory()) {
459→      return toBundle(agent, {
460→        ...state,
461→        warnings: [...state.warnings, `Instructions root does not exist: ${state.rootPath}`],
462→      }, []);
463→    }
464→    const files = await listFilesRecursive(state.rootPath);
465→    const summaries = await Promise.all(files.map((relativePath) => readFileSummary(state.rootPath!, relativePath, state.entryFile)));
466→    return toBundle(agent, state, summaries);
467→  }
468→
469→  async function readFile(agent: AgentLike, relativePath: string): Promise<AgentInstructionsFileDetail> {
470→    const state = await recoverManagedBundleState(agent, deriveBundleState(agent));
471→    if (relativePath === LEGACY_PROMPT_TEMPLATE_PATH) {
472→      const content = asString(state.config[PROMPT_KEY]);
473→      if (content === null) throw notFound("Instructions file not found");
474→      return {
475→        path: LEGACY_PROMPT_TEMPLATE_PATH,
476→        size: content.length,
477→        language: "markdown",
478→        markdown: true,
479→        isEntryFile: false,
480→        editable: true,
481→        deprecated: true,
482→        virtual: true,
483→        content,
484→      };
485→    }
486→    if (!state.rootPath) throw notFound("Agent instructions bundle is not configured");
487→    const absolutePath = resolvePathWithinRoot(state.rootPath, relativePath);
488→    const [content, stat] = await Promise.all([
489→      fs.readFile(absolutePath, "utf8").catch(() => null),
490→      fs.stat(absolutePath).catch(() => null),
491→    ]);
492→    if (content === null || !stat?.isFile()) throw notFound("Instructions file not found");
493→    const normalizedPath = normalizeRelativeFilePath(relativePath);
494→    return {
495→      path: normalizedPath,
496→      size: stat.size,
497→      language: inferLanguage(normalizedPath),
498→      markdown: isMarkdown(normalizedPath),
499→      isEntryFile: normalizedPath === state.entryFile,
500→      editable: true,
501→      deprecated: false,
502→      virtual: false,
503→      content,
504→    };
505→  }
506→
507→  async function ensureWritableBundle(
508→    agent: AgentLike,
509→    options?: { clearLegacyPromptTemplate?: boolean },
510→  ): Promise<{ adapterConfig: Record<string, unknown>; state: BundleState }> {
511→    const derived = deriveBundleState(agent);
512→    const current = await recoverManagedBundleState(agent, derived);
513→    if (current.rootPath && current.mode) {
514→      const adapterConfig = buildPersistedBundleConfig(derived, current, options);
515→      return {
516→        adapterConfig,
517→        state: deriveBundleState({ ...agent, adapterConfig }),
518→      };
519→    }
520→
521→    const managedRoot = resolveManagedInstructionsRoot(agent);
522→    const entryFile = current.entryFile || ENTRY_FILE_DEFAULT;
523→    const nextConfig = applyBundleConfig(current.config, {
524→      mode: "managed",
525→      rootPath: managedRoot,
526→      entryFile,
527→      clearLegacyPromptTemplate: options?.clearLegacyPromptTemplate,
528→    });
529→    await fs.mkdir(managedRoot, { recursive: true });
530→
531→    const entryPath = resolvePathWithinRoot(managedRoot, entryFile);
532→    const entryStat = await statIfExists(entryPath);
533→    if (!entryStat?.isFile()) {
534→      const legacyInstructions = await readLegacyInstructions(agent, current.config);
535→      if (legacyInstructions.trim().length > 0) {
536→        await fs.mkdir(path.dirname(entryPath), { recursive: true });
537→        await fs.writeFile(entryPath, legacyInstructions, "utf8");
538→      }
539→    }
540→
541→    return {
542→      adapterConfig: nextConfig,
543→      state: deriveBundleState({ ...agent, adapterConfig: nextConfig }),
544→    };
545→  }
546→
547→  async function updateBundle(
548→    agent: AgentLike,
549→    input: {
550→      mode?: BundleMode;
551→      rootPath?: string | null;
552→      entryFile?: string;
553→      clearLegacyPromptTemplate?: boolean;
554→    },
555→  ): Promise<{ bundle: AgentInstructionsBundle; adapterConfig: Record<string, unknown> }> {
556→    const state = await recoverManagedBundleState(agent, deriveBundleState(agent));
557→    const nextMode = input.mode ?? state.mode ?? "managed";
558→    const nextEntryFile = input.entryFile ? normalizeRelativeFilePath(input.entryFile) : state.entryFile;
559→    let nextRootPath: string;
560→
561→    if (nextMode === "managed") {
562→      nextRootPath = resolveManagedInstructionsRoot(agent);
563→    } else {
564→      const rootPath = asString(input.rootPath) ?? state.rootPath;
565→      if (!rootPath) {
566→        throw unprocessable("External instructions bundles require an absolute rootPath");
567→      }
568→      const resolvedRoot = resolveHomeAwarePath(rootPath);
569→      if (!path.isAbsolute(resolvedRoot)) {
570→        throw unprocessable("External instructions bundles require an absolute rootPath");
571→      }
572→      nextRootPath = resolvedRoot;
573→    }
574→
575→    await fs.mkdir(nextRootPath, { recursive: true });
576→
577→    const existingFiles = await listFilesRecursive(nextRootPath);
578→    const exported = await exportFiles(agent);
579→    if (existingFiles.length === 0) {
580→      await writeBundleFiles(nextRootPath, exported.files);
581→    }
582→    const refreshedFiles = existingFiles.length === 0 ? await listFilesRecursive(nextRootPath) : existingFiles;
583→    if (!refreshedFiles.includes(nextEntryFile)) {
584→      const nextEntryContent = exported.files[nextEntryFile] ?? exported.files[exported.entryFile] ?? "";
585→      await writeBundleFiles(nextRootPath, { [nextEntryFile]: nextEntryContent });
586→    }
587→
588→    const nextConfig = applyBundleConfig(state.config, {
589→      mode: nextMode,
590→      rootPath: nextRootPath,
591→      entryFile: nextEntryFile,
592→      clearLegacyPromptTemplate: input.clearLegacyPromptTemplate,
593→    });
594→    const nextBundle = await getBundle({ ...agent, adapterConfig: nextConfig });
595→    return { bundle: nextBundle, adapterConfig: nextConfig };
596→  }
597→
598→  async function writeFile(
599→    agent: AgentLike,
600→    relativePath: string,
601→    content: string,
602→    options?: { clearLegacyPromptTemplate?: boolean },
603→  ): Promise<{
604→    bundle: AgentInstructionsBundle;
605→    file: AgentInstructionsFileDetail;
606→    adapterConfig: Record<string, unknown>;
607→  }> {
608→    const current = deriveBundleState(agent);
609→    if (relativePath === LEGACY_PROMPT_TEMPLATE_PATH) {
610→      const adapterConfig: Record<string, unknown> = {
611→        ...current.config,
612→        [PROMPT_KEY]: content,
613→      };
614→      const nextAgent = { ...agent, adapterConfig };
615→      const [bundle, file] = await Promise.all([
616→        getBundle(nextAgent),
617→        readFile(nextAgent, LEGACY_PROMPT_TEMPLATE_PATH),
618→      ]);
619→      return { bundle, file, adapterConfig };
620→    }
621→
622→    const prepared = await ensureWritableBundle(agent, options);
623→    const absolutePath = resolvePathWithinRoot(prepared.state.rootPath!, relativePath);
624→    await fs.mkdir(path.dirname(absolutePath), { recursive: true });
625→    await fs.writeFile(absolutePath, content, "utf8");
626→    const nextAgent = { ...agent, adapterConfig: prepared.adapterConfig };
627→    const [bundle, file] = await Promise.all([
628→      getBundle(nextAgent),
629→      readFile(nextAgent, relativePath),
630→    ]);
631→    return { bundle, file, adapterConfig: prepared.adapterConfig };
632→  }
633→
634→  async function deleteFile(agent: AgentLike, relativePath: string): Promise<{
635→    bundle: AgentInstructionsBundle;
636→    adapterConfig: Record<string, unknown>;
637→  }> {
638→    const derived = deriveBundleState(agent);
639→    const state = await recoverManagedBundleState(agent, derived);
640→    if (relativePath === LEGACY_PROMPT_TEMPLATE_PATH) {
641→      throw unprocessable("Cannot delete the legacy promptTemplate pseudo-file");
642→    }
643→    if (!state.rootPath) throw notFound("Agent instructions bundle is not configured");
644→    const normalizedPath = normalizeRelativeFilePath(relativePath);
645→    if (normalizedPath === state.entryFile) {
646→      throw unprocessable("Cannot delete the bundle entry file");
647→    }
648→    const absolutePath = resolvePathWithinRoot(state.rootPath, normalizedPath);
649→    await fs.rm(absolutePath, { force: true });
650→    const adapterConfig = buildPersistedBundleConfig(derived, state);
651→    const bundle = await getBundle({ ...agent, adapterConfig });
652→    return { bundle, adapterConfig };
653→  }
654→
655→  async function exportFiles(agent: AgentLike): Promise<{
656→    files: Record<string, string>;
657→    entryFile: string;
658→    warnings: string[];
659→  }> {
660→    const state = await recoverManagedBundleState(agent, deriveBundleState(agent));
661→    if (state.rootPath) {
662→      const stat = await statIfExists(state.rootPath);
663→      if (stat?.isDirectory()) {
664→        const relativePaths = await listFilesRecursive(state.rootPath);
665→        const files = Object.fromEntries(await Promise.all(relativePaths.map(async (relativePath) => {
666→          const absolutePath = resolvePathWithinRoot(state.rootPath!, relativePath);
667→          const content = await fs.readFile(absolutePath, "utf8");
668→          return [relativePath, content] as const;
669→        })));
670→        if (Object.keys(files).length > 0) {
671→          return { files, entryFile: state.entryFile, warnings: state.warnings };
672→        }
673→      }
674→    }
675→
676→    const legacyBody = await readLegacyInstructions(agent, state.config);
677→    return {
678→      files: { [state.entryFile]: legacyBody || "_No AGENTS instructions were resolved from current agent config._" },
679→      entryFile: state.entryFile,
680→      warnings: state.warnings,
681→    };
682→  }
683→
684→  async function materializeManagedBundle(
685→    agent: AgentLike,
686→    files: Record<string, string>,
687→    options?: {
688→      clearLegacyPromptTemplate?: boolean;
689→      replaceExisting?: boolean;
690→      entryFile?: string;
691→    },
692→  ): Promise<{ bundle: AgentInstructionsBundle; adapterConfig: Record<string, unknown> }> {
693→    const rootPath = resolveManagedInstructionsRoot(agent);
694→    const entryFile = options?.entryFile ? normalizeRelativeFilePath(options.entryFile) : ENTRY_FILE_DEFAULT;
695→
696→    if (options?.replaceExisting) {
697→      await fs.rm(rootPath, { recursive: true, force: true });
698→    }
699→    await fs.mkdir(rootPath, { recursive: true });
700→
701→    const normalizedEntries = Object.entries(files).map(([relativePath, content]) => [
702→      normalizeRelativeFilePath(relativePath),
703→      content,
704→    ] as const);
705→    for (const [relativePath, content] of normalizedEntries) {
706→      const absolutePath = resolvePathWithinRoot(rootPath, relativePath);
707→      await fs.mkdir(path.dirname(absolutePath), { recursive: true });
708→      await fs.writeFile(absolutePath, content, "utf8");
709→    }
710→    if (!normalizedEntries.some(([relativePath]) => relativePath === entryFile)) {
711→      await fs.writeFile(resolvePathWithinRoot(rootPath, entryFile), "", "utf8");
712→    }
713→
714→    const adapterConfig = applyBundleConfig(asRecord(agent.adapterConfig), {
715→      mode: "managed",
716→      rootPath,
717→      entryFile,
718→      clearLegacyPromptTemplate: options?.clearLegacyPromptTemplate,
719→    });
720→    const bundle = await getBundle({ ...agent, adapterConfig });
721→    return { bundle, adapterConfig };
722→  }
723→
724→  return {
725→    getBundle,
726→    readFile,
727→    updateBundle,
728→    writeFile,
729→    deleteFile,
730→    exportFiles,
731→    ensureManagedBundle: ensureWritableBundle,
732→    materializeManagedBundle,
733→  };
734→}
