    const projectRoot = resolveProjectRoot();
    if (projectRoot) {
      return path.resolve(projectRoot, ".paperclip", "workspaces", trimmed);
    }
  }

  return path.resolve(resolvePaperclipInstanceRoot(), "workspaces", trimmed);
}
