 11→export interface BootstrapResult {
 12→  action: "created_company" | "assigned_to_company" | "noop";
 13→  companyId?: string;
 14→}
 15→
 16→export function bootstrapService(db: Db) {
 17→  const isEnabled = process.env.PAPERCLIP_AUTO_BOOTSTRAP !== "false";
 18→
 19→  async function maybeBootstrapUser(
 20→    userId: string,
 21→    userName?: string | null,
 22→  ): Promise<BootstrapResult> {
 23→    if (!isEnabled) return { action: "noop" };
 24→
 25→    // Check if user already has any company memberships
 26→    const existingMemberships = await db
 27→      .select({ id: companyMemberships.id })
 28→      .from(companyMemberships)
 29→      .where(
 30→        and(
 31→          eq(companyMemberships.principalType, "user"),
 32→          eq(companyMemberships.principalId, userId),
 33→          eq(companyMemberships.status, "active"),
 34→        ),
 35→      )
 36→      .limit(1);
 37→
 38→    if (existingMemberships.length > 0) {
 39→      return { action: "noop" };
 40→    }
 41→
 42→    // Check if any companies exist
 43→    const [companyCount] = await db
 44→      .select({ count: count() })
 45→      .from(companies);
 46→
 47→    if (companyCount.count === 0) {
 48→      // First user: create default company + agent, promote to admin
 49→      return createDefaultSetup(userId, userName);
 50→    }
 51→
 52→    // Companies exist but user has no membership: assign to first company
 53→    const [firstCompany] = await db
 54→      .select({ id: companies.id })
 55→      .from(companies)
 56→      .limit(1);
 57→
 58→    if (firstCompany) {
 59→      await db.insert(companyMemberships).values({
 60→        companyId: firstCompany.id,
 61→        principalType: "user",
 62→        principalId: userId,
 63→        status: "active",
 64→        membershipRole: "member",
 65→      });
 66→
 67→      logger.info(
 68→        { userId, companyId: firstCompany.id },
 69→        "Auto-assigned user to existing company",
 70→      );
 71→
 72→      return { action: "assigned_to_company", companyId: firstCompany.id };
 73→    }
 74→
 75→    return { action: "noop" };
 76→  }
 77→
 78→  async function createDefaultSetup(
 79→    userId: string,
 80→    userName?: string | null,
 81→  ): Promise<BootstrapResult> {
 82→    const companyName =
 83→      process.env.PAPERCLIP_DEFAULT_COMPANY_NAME || "My Company";
 84→    const agentName =
 85→      process.env.PAPERCLIP_DEFAULT_AGENT_NAME || "CEO Agent";
 86→
 87→    // Create company
 88→    const [company] = await db
 89→      .insert(companies)
 90→      .values({ name: companyName })
 91→      .returning();
 92→
 93→    // Promote user to instance_admin
 94→    const existingRole = await db
 95→      .select({ id: instanceUserRoles.id })
 96→      .from(instanceUserRoles)
 97→      .where(
 98→        and(
 99→          eq(instanceUserRoles.userId, userId),
100→          eq(instanceUserRoles.role, "instance_admin"),
101→        ),
102→      )
103→      .then((rows) => rows[0] ?? null);
104→
105→    if (!existingRole) {
106→      await db.insert(instanceUserRoles).values({
107→        userId,
108→        role: "instance_admin",
109→      });
110→    }
111→
112→    // Assign user as owner
113→    await db.insert(companyMemberships).values({
114→      companyId: company.id,
115→      principalType: "user",
116→      principalId: userId,
117→      status: "active",
118→      membershipRole: "owner",
119→    });
120→
121→    // Create default CEO agent
122→    await db.insert(agents).values({
123→      companyId: company.id,
124→      name: agentName,
125→      role: "ceo",
126→      title: "Chief Executive Officer",
127→      adapterType: "claude-local",
128→    });
129→
130→    logger.info(
131→      { userId, companyId: company.id, companyName, agentName },
132→      "Auto-bootstrap: created default company and agent for first user",
133→    );
134→
135→    return { action: "created_company", companyId: company.id };
