627→  router.post("/plugins/install", async (req, res) => {
628→    assertBoard(req);
629→    const { packageName, version, isLocalPath } = req.body as PluginInstallRequest;
630→
631→    // Input validation
632→    if (!packageName || typeof packageName !== "string") {
633→      res.status(400).json({ error: "packageName is required and must be a string" });
634→      return;
635→    }
636→
637→    if (version !== undefined && typeof version !== "string") {
638→      res.status(400).json({ error: "version must be a string if provided" });
639→      return;
640→    }
641→
642→    if (isLocalPath !== undefined && typeof isLocalPath !== "boolean") {
643→      res.status(400).json({ error: "isLocalPath must be a boolean if provided" });
644→      return;
645→    }
646→
647→    // Validate package name format
648→    const trimmedPackage = packageName.trim();
649→    if (trimmedPackage.length === 0) {
650→      res.status(400).json({ error: "packageName cannot be empty" });
651→      return;
652→    }
653→
654→    // Basic security check for package name (prevent injection)
655→    if (!isLocalPath && /[<>:"|?*]/.test(trimmedPackage)) {
656→      res.status(400).json({ error: "packageName contains invalid characters" });
657→      return;
658→    }
659→
660→    try {
661→      const installOptions = isLocalPath
662→        ? { localPath: trimmedPackage }
663→        : { packageName: trimmedPackage, version: version?.trim() };
664→
665→      const discovered = await loader.installPlugin(installOptions);
666→
667→      if (!discovered.manifest) {
668→        res.status(500).json({ error: "Plugin installed but manifest is missing" });
669→        return;
670→      }
671→
672→      // Transition to ready state
673→      const existingPlugin = await registry.getByKey(discovered.manifest.id);
674→      if (existingPlugin) {
675→        await lifecycle.load(existingPlugin.id);
676→        const updated = await registry.getById(existingPlugin.id);
677→        await logPluginMutationActivity(req, "plugin.installed", existingPlugin.id, {
678→          pluginId: existingPlugin.id,
679→          pluginKey: existingPlugin.pluginKey,
680→          packageName: updated?.packageName ?? existingPlugin.packageName,
681→          version: updated?.version ?? existingPlugin.version,
682→          source: isLocalPath ? "local_path" : "npm",
683→        });
684→        publishGlobalLiveEvent({ type: "plugin.ui.updated", payload: { pluginId: existingPlugin.id, action: "installed" } });
685→        res.json(updated);
686→      } else {
687→        // This shouldn't happen since installPlugin already registers in the DB
688→        res.status(500).json({ error: "Plugin installed but not found in registry" });
689→      }
690→    } catch (err) {
691→      const message = err instanceof Error ? err.message : String(err);
692→      res.status(400).json({ error: message });
693→    }
