731→  /**
732→   * Map a worker RPC error to a bridge-level error code.
733→   *
734→   * JsonRpcCallError carries numeric codes from the plugin RPC error code space.
735→   * This helper maps them to the string error codes defined in PluginBridgeErrorCode.
736→   *
737→   * @see PLUGIN_SPEC.md §19.7 — Error Propagation Through The Bridge
738→   */
739→  function mapRpcErrorToBridgeError(err: unknown): PluginBridgeErrorResponse {
740→    if (err instanceof JsonRpcCallError) {
741→      switch (err.code) {
742→        case PLUGIN_RPC_ERROR_CODES.WORKER_UNAVAILABLE:
743→          return {
744→            code: "WORKER_UNAVAILABLE",
745→            message: err.message,
746→            details: err.data,
747→          };
748→        case PLUGIN_RPC_ERROR_CODES.CAPABILITY_DENIED:
749→          return {
750→            code: "CAPABILITY_DENIED",
751→            message: err.message,
752→            details: err.data,
753→          };
754→        case PLUGIN_RPC_ERROR_CODES.TIMEOUT:
755→          return {
756→            code: "TIMEOUT",
757→            message: err.message,
758→            details: err.data,
759→          };
760→        case PLUGIN_RPC_ERROR_CODES.WORKER_ERROR:
761→          return {
762→            code: "WORKER_ERROR",
763→            message: err.message,
764→            details: err.data,
765→          };
766→        default:
767→          return {
768→            code: "UNKNOWN",
