1295→      pluginId: string,
1296→      upgradeOptions: Omit<PluginInstallOptions, "installDir">,
1297→    ): Promise<{
1298→      oldManifest: PaperclipPluginManifestV1;
1299→      newManifest: PaperclipPluginManifestV1;
1300→      discovered: DiscoveredPlugin;
1301→    }> {
1302→      const plugin = (await registry.getById(pluginId)) as {
1303→        id: string;
1304→        packageName: string;
1305→        packagePath: string | null;
1306→        manifestJson: PaperclipPluginManifestV1;
1307→      } | null;
1308→      if (!plugin) throw new Error(`Plugin not found: ${pluginId}`);
1309→
1310→      const oldManifest = plugin.manifestJson;
1311→      const {
1312→        packageName = plugin.packageName,
1313→        // For local-path installs, fall back to the stored packagePath so
1314→        // `upgradePlugin` can re-read the manifest from disk without needing
1315→        // the caller to re-supply the path every time.
1316→        localPath = plugin.packagePath ?? undefined,
1317→        version,
1318→      } = upgradeOptions;
1319→
1320→      log.info(
1321→        { pluginId, packageName, version, localPath },
1322→        "plugin-loader: upgrading plugin",
1323→      );
1324→
1325→      // 1. Fetch/Install the new version
1326→      const discovered = await fetchAndValidate({
1327→        packageName,
1328→        localPath,
1329→        version,
1330→        installDir: localPluginDir,
1331→      });
1332→
1333→      const newManifest = discovered.manifest!;
1334→
1335→      // 2. Validate it's the same plugin ID
1336→      if (newManifest.id !== oldManifest.id) {
1337→        throw new Error(
1338→          `Upgrade failed: new manifest ID '${newManifest.id}' does not match existing plugin ID '${oldManifest.id}'`,
1339→        );
1340→      }
1341→
1342→      // 3. Detect capability escalation — new capabilities not in the old manifest
1343→      const oldCaps = new Set(oldManifest.capabilities ?? []);
1344→      const newCaps = newManifest.capabilities ?? [];
1345→      const escalated = newCaps.filter((c) => !oldCaps.has(c));
1346→
1347→      if (escalated.length > 0) {
1348→        log.warn(
1349→          { pluginId, escalated, oldVersion: oldManifest.version, newVersion: newManifest.version },
1350→          "plugin-loader: upgrade introduces new capabilities — requires admin approval",
1351→        );
1352→        throw new Error(
1353→          `Upgrade for "${pluginId}" introduces new capabilities that require approval: ${escalated.join(", ")}. ` +
1354→            `The previous version declared [${[...oldCaps].join(", ")}]. ` +
1355→            `Please review and approve the capability escalation before upgrading.`,
1356→        );
1357→      }
1358→
1359→      // 4. Update the existing record
1360→      await registry.update(pluginId, {
1361→        packageName: discovered.packageName,
1362→        version: discovered.version,
1363→        manifest: newManifest,
1364→      });
1365→
1366→      return {
1367→        oldManifest,
1368→        newManifest,
1369→        discovered,
1370→      };
1371→    },
